import{_ as a,o as t,c as o,ai as n}from"./chunks/framework.DQi1ytmF.js";const u=JSON.parse('{"title":"Type-safe i18n","description":"","frontmatter":{},"headers":[],"relativePath":"guide/i18n/index.md","filePath":"guide/i18n/index.md"}'),s={name:"guide/i18n/index.md"};function i(r,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/i18n.md for this page in Markdown format</div><h1 id="type-safe-i18n" tabindex="-1">Type-safe i18n <a class="header-anchor" href="#type-safe-i18n" aria-label="Permalink to &quot;Type-safe i18n&quot;">​</a></h1><p><code>@craft-ts/i18n</code> has <strong>no CraftTS, Angular or Effect import</strong>. The catalogue is a plain TypeScript value and the runtime works in a browser, a server, a worker or a test without a framework. That is not a packaging detail — it is what lets the same catalogue be checked by <code>tsc</code>, exercised by a Node test, and rendered during SSR without a second implementation.</p><h2 id="the-contract" tabindex="-1">The contract <a class="header-anchor" href="#the-contract" aria-label="Permalink to &quot;The contract&quot;">​</a></h2><p>Four things are guaranteed, and all four are checked before the app runs.</p><table tabindex="0"><thead><tr><th>guarantee</th><th>what it costs you to break</th></tr></thead><tbody><tr><td>the key set is a <strong>closed union</strong></td><td>an unknown key does not compile — no silent <code>order.totl</code></td></tr><tr><td>every locale has the <strong>same keys with the same parameters</strong></td><td>a translation you forgot is a compile error, not a fallback</td></tr><tr><td>parameters are <strong>typed by their token</strong></td><td>a date cannot be passed where a currency amount belongs</td></tr><tr><td>a plural carries <strong>every category the locale requires</strong></td><td>Polish needs <code>one</code>/<code>few</code>/<code>many</code>/<code>other</code>; French needs <code>one</code>/<code>other</code></td></tr></tbody></table><p>The usual failure mode of a translation layer is that all four of these are runtime concerns: a missing key renders its own name, a wrong parameter renders <code>[object Object]</code>, and a missing plural category renders the wrong branch to the users of one locale only. None of that is observable from the code that calls <code>t</code>.</p><h2 id="the-shape-of-it" tabindex="-1">The shape of it <a class="header-anchor" href="#the-shape-of-it" aria-label="Permalink to &quot;The shape of it&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/i18n/</span></span>
<span class="line"><span>  catalog.ts          the reference locale — defineCatalog + msg + plural</span></span>
<span class="line"><span>  locales/fr-FR.ts    every other locale — defineLocaleLike</span></span>
<span class="line"><span>  project-tokens.ts   business tokens: defineToken / defineTokenFactory</span></span>
<span class="line"><span>  runtime.ts          createI18nRuntime, and the reactive binding</span></span></code></pre></div><p>A key is its dotted path: <code>order.total</code> reaches <code>{ order: { total: msg</code>…<code> } }</code>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./catalog.html">The catalogue</a> — <code>defineCatalog</code>, <code>msg</code>, <code>plural</code>, <code>defineLocale</code>, <code>defineLocaleLike</code>.</li><li><a href="./tokens.html">Tokens</a> — the shipped semantic tokens, and how to add your own.</li><li><a href="./runtime.html">The runtime</a> — <code>createI18nRuntime</code>, <code>t</code>, <code>bind</code>, lazy locales.</li><li><a href="./effect.html">With Effect</a> — <code>@craft-ts/i18n-effect</code>.</li></ul><p>Two checks belong in CI, and <code>craft create</code> wires both:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:test</span></span></code></pre></div><p>A working example lives in the demo, at <code>apps/demo/src/app/examples/i18n/</code>.</p>`,15)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
